<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
$game = $args['game']; $month = $args['month'];
$values = khaiwal_results_for_month( $game, $month->format( 'Y-m' ) );
$days = (int) $month->format( 't' );
$month_id = 'results-' . $month->format( 'Y-m' );
?>
<div class="month-card"><div class="month-card-head"><div><small><?php echo khaiwal_text( 'MONTHLY RECORD', 'महीने का रिकॉर्ड' ); ?></small><h2 id="<?php echo esc_attr( $month_id ); ?>" data-month-label="<?php echo esc_attr( $month->format( 'Y-m' ) ); ?>"><?php echo esc_html( $month->format( 'F Y' ) ); ?></h2></div><span><?php echo khaiwal_icon( 'calendar' ); ?></span></div><div class="month-table-wrap" tabindex="0" role="region" aria-labelledby="<?php echo esc_attr( $month_id ); ?>" aria-describedby="<?php echo esc_attr( $month_id . '-help' ); ?>"><table><thead><tr><th scope="col"><?php echo khaiwal_text( 'DATE', 'तारीख' ); ?></th><th scope="col"><?php echo khaiwal_text( 'RESULT', 'रिज़ल्ट' ); ?></th></tr></thead><tbody><?php for ( $day = 1; $day <= $days; $day++ ) : $key = sprintf( '%s-%02d', $month->format( 'Y-m' ), $day ); ?><tr><th scope="row" data-result-date="<?php echo esc_attr( $key ); ?>"><?php echo esc_html( sprintf( '%02d %s', $day, $month->format( 'M' ) ) ); ?></th><td class="<?php echo isset( $values[ $key ] ) ? 'has-number' : 'no-number'; ?>"><?php echo khaiwal_result_html( isset( $values[ $key ] ) ? $values[ $key ] : '', $key === khaiwal_now()->format( 'Y-m-d' ) ); // phpcs:ignore WordPress.Security.EscapeOutput ?></td></tr><?php endfor; ?></tbody></table></div><div class="month-card-footer" id="<?php echo esc_attr( $month_id . '-help' ); ?>"><?php echo khaiwal_text( 'Scroll to see all dates', 'सभी तारीखें देखने के लिए स्क्रॉल करें' ); ?> <span aria-hidden="true">↓</span></div></div>
